// German copy (de-DE). Natural, informal-singular («du») German for a women's health application — NOT a literal
// word-for-word rendering of en.ts. Same key set, same interpolation placeholders and the same plural keys
// (_one/_other: German has exactly the English two forms, "1 Tag" / "2 Tage") as the other dictionaries.
//
// Conventions: «du» (like the French «tu» and Turkish «sen» copy) with lower-case du/dein; „…“ for quotation marks;
// the typed destructive-confirmation word is «LÖSCHEN»; the partner feature is «AWA Gemeinsam»; language names
// are endonyms («Deutsch»). Medical terms use the everyday German word with the clinical one in the educational text
// (Periode / Regelblutung / Menstruation, Eisprung, Gelbkörperphase / Lutealphase, Wochenbett). Religious-practice
// terms keep the common transliterations (Gebet, Fasten, Qada, Nifas, Istihada, Ghusl, Hidschri-Kalender) and stay
// neutral and educational — the wording still needs scholar validation, exactly as in the other languages.
